  // Benchmarks page
  'bench.meta_title': { en: 'RTK Benchmarks: Token & Cost Savings by Ecosystem | rtk-ai', fr: 'Benchmarks RTK : Économies de tokens et de coûts par écosystème | rtk-ai', es: 'Benchmarks RTK: Ahorro de tokens y costos por ecosistema | rtk-ai', de: 'RTK-Benchmarks: Token- und Kostenersparnis nach Ökosystem | rtk-ai', zh: 'RTK 基准测试：按生态系统划分的 Token 和成本节省 | rtk-ai', ja: 'RTK ベンチマーク：エコシステム別のトークン・コスト削減 | rtk-ai' },
  'bench.meta_desc': { en: 'Measured RTK savings across JavaScript, TypeScript, Python, Rust, Go and .NET: cost, tokens, pass rate and p-values, per RTK version. Interactive charts and downloadable reports.', fr: 'Économies RTK mesurées sur JavaScript, TypeScript, Python, Rust, Go et .NET : coût, tokens, taux de réussite et p-values, par version de RTK. Graphiques interactifs et rapports téléchargeables.', es: 'Ahorros de RTK medidos en JavaScript, TypeScript, Python, Rust, Go y .NET: costo, tokens, tasa de aprobación y p-values, por versión de RTK. Gráficos interactivos e informes descargables.', de: 'Gemessene RTK-Einsparungen über JavaScript, TypeScript, Python, Rust, Go und .NET: Kosten, Tokens, Erfolgsquote und p-Werte, pro RTK-Version. Interaktive Diagramme und herunterladbare Berichte.', zh: '在 JavaScript、TypeScript、Python、Rust、Go 和 .NET 上测量的 RTK 节省（）按 RTK 版本统计成本、token、通过率和 p 值。交互式图表和可下载报告。', ja: 'JavaScript、TypeScript、Python、Rust、Go、.NET で測定した RTK の削減効果（）RTK バージョンごとのコスト、トークン、合格率、p 値。インタラクティブなグラフとダウンロード可能なレポート。' },
  'bench.hero_title': { en: 'benchmarks', fr: 'benchmarks', es: 'benchmarks', de: 'Benchmarks', zh: '基准测试', ja: 'ベンチマーク' },
  'bench.hero_sub': { en: 'Code reviews sessions run with and without RTK on the same tasks. Browse by <strong>RTK version</strong>, then by <strong>ecosystem</strong>.', fr: 'Sessions de revue de code exécutées avec et sans RTK sur les mêmes tâches. Parcourez par <strong>version de RTK</strong>, puis par <strong>écosystème</strong>.', es: 'Sesiones de revisión de código ejecutadas con y sin RTK en las mismas tareas. Explora por <strong>versión de RTK</strong>, luego por <strong>ecosistema</strong>.', de: 'Code-Review-Sessions mit und ohne RTK bei denselben Aufgaben. Stöbere nach <strong>RTK-Version</strong>, dann nach <strong>Ökosystem</strong>.', zh: '在相同任务上运行带 RTK 和不带 RTK 的代码审查会话。按 <strong>RTK 版本</strong>浏览，然后按<strong>生态系统</strong>浏览。', ja: '同じタスクで RTK あり・なしのコードレビューセッションを実行。<strong>RTK バージョン</strong>別、次に<strong>エコシステム</strong>別に閲覧できます。' },
