  'v3.hero.intro_tag': { en: 'Your AI agent drowns in noise.<br /><strong>RTK cleans it up.</strong>', fr: 'Votre agent IA se noie dans le bruit.<br /><strong>RTK fait le ménage.</strong>', es: 'Tu agente IA se ahoga en ruido.<br /><strong>RTK lo limpia.</strong>', de: 'Dein KI-Agent ertrinkt im Rauschen.<br /><strong>RTK räumt auf.</strong>', zh: '你的 AI 代理正淹没在噪音中。<br /><strong>RTK 帮它清理。</strong>', ja: 'AI エージェントはノイズに埋もれている。<br /><strong>RTK が片づける。</strong>' },
  'v3.hero.scroll_cue': { en: 'See how it works', fr: 'Voir comment ça marche', es: 'Mira cómo funciona', de: 'So funktioniert es', zh: '看看它如何运作', ja: '仕組みを見る' },
  'v3.hero.pro_chip': { en: '<strong>RTK Pro</strong>: the AI Control Layer for your team', fr: '<strong>RTK Pro</strong> : la couche de contrôle IA de votre équipe', es: '<strong>RTK Pro</strong>: la capa de control de IA para tu equipo', de: '<strong>RTK Pro</strong>: der AI Control Layer für dein Team', zh: '<strong>RTK Pro</strong>：团队的 AI 控制层', ja: '<strong>RTK Pro</strong>：チームのための AI コントロールレイヤー' },
  'v3.hero.title': { en: 'Clean context<br /><em>Better agents</em>', fr: 'Contexte propre<br /><em>Meilleurs agents</em>', es: 'Contexto limpio<br /><em>Mejores agentes</em>', de: 'Sauberer Kontext<br /><em>Bessere Agenten</em>', zh: '干净的上下文。<br /><em>更强的代理。</em>', ja: 'クリーンなコンテキスト。<br /><em>より賢いエージェント。</em>' },
  'v3.hero.cta_install': { en: 'Install RTK', fr: 'Installer RTK', es: 'Instalar RTK', de: 'RTK installieren', zh: '安装 RTK', ja: 'RTK をインストール' },
  'v3.hero.cta_github': { en: 'View on GitHub', fr: 'Voir sur GitHub', es: 'Ver en GitHub', de: 'Auf GitHub ansehen', zh: '在 GitHub 查看', ja: 'GitHub で見る' },
  'v3.hero.meta': { en: 'Open source · Apache 2.0 · Rust', fr: 'Open source · Apache 2.0 · Rust', es: 'Open source · Apache 2.0 · Rust', de: 'Open Source · Apache 2.0 · Rust', zh: '开源 · Apache 2.0 · Rust', ja: 'オープンソース · Apache 2.0 · Rust' },
  'v3.hero.visual_sr': { en: 'Diagram: a dense grid of tokens fills 86% of the AI context window, close to autocompact. It flows through the RTK filter, which strips the CLI output noise and leaves the meaningful lines: the same window back down to 73% used, with room to think.', fr: "Schéma : une grille dense de tokens occupe 86 % de la fenêtre de contexte de l'IA, proche du compactage automatique. Elle traverse le filtre RTK, qui retire le bruit des sorties CLI et conserve les lignes utiles : la même fenêtre redescend à 73 % utilisés, avec de la place pour raisonner.", es: 'Diagrama: una cuadrícula densa de tokens llena el 86 % de la ventana de contexto de la IA, cerca de la compactación automática. Pasa por el filtro de RTK, que elimina el ruido de la salida CLI y conserva las líneas útiles: la misma ventana baja al 73 % usado, con espacio para razonar.', de: 'Diagramm: ein dichtes Token-Raster füllt 86 % des KI-Kontextfensters, kurz vor dem automatischen Komprimieren. Es läuft durch den RTK-Filter, der das CLI-Ausgaberauschen entfernt und die sinnvollen Zeilen behält: dasselbe Fenster sinkt auf 73 % Auslastung, mit Raum zum Denken.', zh: '示意图：密集的 token 网格占满 AI 上下文窗口的 86%，接近自动压缩。它流经 RTK 过滤器，滤除 CLI 输出噪音并保留有意义的内容：同一窗口回落到 73% 占用，留出思考空间。', ja: '図：トークンの密なグリッドが AI コンテキストウィンドウの 86% を占め、自動圧縮の直前です。RTK フィルターを通ると CLI 出力のノイズが取り除かれ、意味のある行が残ります：同じウィンドウが 73% 使用まで下がり、考える余地が生まれます。' },
