  'v3.proof.eyebrow': { en: 'The evidence', fr: 'Les preuves', es: 'La evidencia', de: 'Der Beleg', zh: '实测证据', ja: '実測データ' },
  'v3.proof.title': { en: "Show your gains, share your <em>pipelines</em>", fr: "Montrez vos gains, partagez vos <em>pipelines</em>", es: "Muestra tus ganancias, comparte tus <em>pipelines</em>", de: "Zeig deine Gewinne, teile deine <em>Pipelines</em>", zh: "展示你的收益，分享你的 <em>pipeline</em>", ja: "成果を見せて、<em>パイプライン</em>を共有しよう" },
  'v3.proof.sub': { en: "Run <code>rtk gain</code> to see what RTK saves you, then share the pipeline behind it in one command.", fr: "Lancez <code>rtk gain</code> pour voir ce que RTK vous fait économiser, puis partagez le pipeline derrière en une commande.", es: "Ejecuta <code>rtk gain</code> para ver lo que RTK te ahorra y comparte el pipeline que hay detrás con un solo comando.", de: "Führe <code>rtk gain</code> aus, um zu sehen, was RTK dir spart, und teile die Pipeline dahinter mit einem Befehl.", zh: "运行 <code>rtk gain</code> 查看 RTK 为你节省了多少，再用一条命令分享背后的 pipeline。", ja: "<code>rtk gain</code> で RTK による節約量を確認し、その裏にあるパイプラインをコマンドひとつで共有しましょう。" },
  'v3.proof.alt1': { en: "rtk gain live dashboard: command filtering savings, RTK Proxy requests and cache hits, context composition, and savings by command", fr: "Tableau de bord rtk gain en direct : économies du filtrage des commandes, requêtes et cache du RTK Proxy, composition du contexte et économies par commande", es: "Panel en vivo de rtk gain: ahorro del filtrado de comandos, peticiones y aciertos de caché del RTK Proxy, composición del contexto y ahorro por comando", de: "rtk gain Live-Dashboard: Einsparungen durch Befehlsfilterung, RTK-Proxy-Anfragen und Cache-Treffer, Kontextzusammensetzung und Einsparungen pro Befehl", zh: "rtk gain 实时面板：命令过滤节省、RTK Proxy 请求与缓存命中、上下文构成，以及按命令统计的节省", ja: "rtk gain ライブダッシュボード：コマンドフィルタリングの節約量、RTK Proxy のリクエストとキャッシュヒット、コンテキスト構成、コマンド別の節約量" },
  'v3.proof.k1': { en: "44.4% saved", fr: "44,4 % économisés", es: "44,4 % ahorrado", de: "44,4 % gespart", zh: "节省 44.4%", ja: "44.4% 削減" },
  'v3.proof.d1': { en: "Live <code>rtk gain</code> from daily use: <strong>41,502 commands, 4.7M tokens saved</strong>.", fr: "<code>rtk gain</code> en direct, en usage quotidien : <strong>41 502 commandes, 4,7 M de tokens économisés</strong>.", es: "<code>rtk gain</code> en vivo, en uso diario: <strong>41.502 comandos, 4,7 M de tokens ahorrados</strong>.", de: "Live-<code>rtk gain</code> aus täglicher Nutzung: <strong>41.502 Befehle, 4,7 Mio. Tokens gespart</strong>.", zh: "日常使用中的实时 <code>rtk gain</code>：<strong>41,502 条命令，节省 470 万 token</strong>。", ja: "日常利用のライブ <code>rtk gain</code>：<strong>41,502 コマンド、470 万トークンを節約</strong>。" },
  'v3.proof.discord': { en: 'See what other developers save in <code>#show-your-gains</code> on Discord', fr: 'Voyez ce que les autres développeurs économisent dans <code>#show-your-gains</code> sur Discord', es: 'Mira lo que ahorran otros desarrolladores en <code>#show-your-gains</code> en Discord', de: 'Sieh in <code>#show-your-gains</code> auf Discord, was andere Entwickler sparen', zh: '在 Discord 的 <code>#show-your-gains</code> 频道查看其他开发者的节省数据', ja: 'Discord の <code>#show-your-gains</code> で他の開発者の節約量を見る' },
  'v3.proof.g_saved': { en: "tokens saved", fr: "tokens économisés", es: "tokens ahorrados", de: "Tokens gespart", zh: "节省的 token", ja: "節約したトークン" },
  'v3.proof.g_less': { en: "less command output", fr: "de sortie de commande en moins", es: "menos salida de comandos", de: "weniger Befehlsausgabe", zh: "命令输出减少", ja: "コマンド出力を削減" },
  'v3.proof.s_public': { en: "Public", fr: "Public", es: "Público", de: "Öffentlich", zh: "公开", ja: "公開" },
  'v3.proof.s_runs': { en: "Runs in", fr: "Fonctionne dans", es: "Funciona en", de: "Läuft in", zh: "可运行于", ja: "対応エージェント" },
  'v3.proof.s_copied': { en: "Link copied", fr: "Lien copié", es: "Enlace copiado", de: "Link kopiert", zh: "链接已复制", ja: "リンクをコピーしました" },
  'v3.proof.ill_sr': { en: "Illustration: rtk gain shows what RTK saved you, here 4.7M tokens and 44% less command output. rtk pipeline share turns the pipeline behind it into a link, private or public, that runs in Claude Code, Cursor, Codex and 15 more agents.", fr: "Illustration : rtk gain montre ce que RTK vous a fait économiser, ici 4,7 M de tokens et 44 % de sortie de commande en moins. rtk pipeline share transforme le pipeline derrière en un lien, privé ou public, qui fonctionne dans Claude Code, Cursor, Codex et 15 autres agents.", es: "Ilustración: rtk gain muestra lo que RTK te ahorró, aquí 4,7 M de tokens y un 44 % menos de salida de comandos. rtk pipeline share convierte el pipeline que hay detrás en un enlace, privado o público, que funciona en Claude Code, Cursor, Codex y 15 agentes más.", de: "Illustration: rtk gain zeigt, was RTK dir gespart hat, hier 4,7 Mio. Tokens und 44 % weniger Befehlsausgabe. rtk pipeline share macht aus der Pipeline dahinter einen Link, privat oder öffentlich, der in Claude Code, Cursor, Codex und 15 weiteren Agenten läuft.", zh: "示意图：rtk gain 显示 RTK 为你节省了多少，这里是 470 万 token、命令输出减少 44%。rtk pipeline share 把背后的 pipeline 变成一个私有或公开的链接，可在 Claude Code、Cursor、Codex 等 18 个代理中运行。", ja: "図：rtk gain が RTK による節約量を表示（ここでは 470 万トークン、コマンド出力 44% 削減）。rtk pipeline share でその裏にあるパイプラインを非公開または公開のリンクにし、Claude Code、Cursor、Codex など 18 のエージェントで使えます。" },

  'v3.install.eyebrow': { en: 'Get started', fr: 'Démarrer', es: 'Empezar', de: 'Loslegen', zh: '开始使用', ja: 'はじめる' },
  'v3.install.title': { en: 'Running in <em>30 seconds</em>', fr: 'Opérationnel en <em>30 secondes</em>', es: 'Funcionando en <em>30 segundos</em>', de: 'In <em>30 Sekunden</em> startklar', zh: '30 秒即可运行', ja: '30 秒で動き出す' },
  'v3.install.sub': { en: 'Install, activate the hook, and every command is compressed automatically.', fr: 'Installez, activez le hook, et chaque commande est compressée automatiquement.', es: 'Instala, activa el hook y cada comando se comprime automáticamente.', de: 'Installieren, Hook aktivieren, jeder Befehl wird automatisch komprimiert.', zh: '安装、激活钩子，之后每条命令都会被自动压缩。', ja: 'インストールしてフックを有効化すれば、あらゆるコマンドが自動で圧縮されます。' },
  'v3.install.quick': { en: 'Quick install', fr: 'Installation rapide', es: 'Instalación rápida', de: 'Schnellinstallation', zh: '快速安装', ja: 'クイックインストール' },
